import sys
input = sys.stdin.read

def solve():
    data = input().split()
    index = 0
    n, m = int(data[index]), int(data[index + 1])
    index += 2

    A = []
    for i in range(n):
        row = list(map(int, data[index:index + m]))
        index += m
        A.append(row)

    operations = []

    # Iterate over A to determine where to place the 2x2 submatrices
    for i in range(n - 1):
        for j in range(m - 1):
            if A[i][j] == 1 and A[i][j + 1] == 1 and A[i + 1][j] == 1 and A[i + 1][j + 1] == 1:
                operations.append((i + 1, j + 1))

    # Create matrix B from the operations to ensure it matches A
    B = [[0] * m for _ in range(n)]
    for x, y in operations:
        B[x - 1][y - 1] = 1
        B[x - 1][y] = 1
        B[x][y - 1] = 1
        B[x][y] = 1

    # Check if B equals A
    possible = True
    for i in range(n):
        for j in range(m):
            if A[i][j] != B[i][j]:
                possible = False
                break
        if not possible:
            break

    if possible:
        print(len(operations))
        for x, y in operations:
            print(x, y)
    else:
        print(-1)

solve()

